        max: Optional['types.SymptomMaxAggregateInput'] = None,
        having: Optional['types.SymptomScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.SymptomCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.SymptomScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.SymptomScalarFieldKeys', 'types.SortOrder']]]] = None,
